"""Generate the nine independent pages. Run with Python 3; no dependencies."""
from pathlib import Path
from html import escape
import os

ROOT = Path(__file__).parent
OUT = ROOT / 'dist' if (ROOT / '.openai' / 'hosting.json').exists() else ROOT

def t(es, en, tag='span', cls=''):
    return f'<{tag} class="{cls}" data-es="{escape(es, quote=True)}" data-en="{escape(en, quote=True)}">{escape(es)}</{tag}>'

def link(path, es, en, cls='btn'):
    return f'<a class="{cls}" href="@/{path}">{t(es,en)}</a>'

def art():
    return '<div class="art" aria-hidden="true"><div class="sun"></div><div class="shelf"></div><div class="pot"></div><div class="pot two"></div><span class="art-caption">hecho con calma · made slowly</span></div>'

def tile(kind):
    return f'<div class="tile-art detail-art {kind}" aria-hidden="true"></div>'

def head(kicker, kicker_en, title, title_en, desc, desc_en):
    return '<div class="page-head">'+t(kicker,kicker_en,'div','eyebrow')+t(title,title_en,'h1')+t(desc,desc_en,'p','lead')+'</div>'

def page(path, section, title, title_en, content, activity='', crm=False):
    links=[('index.html','Inicio','Home','home'),('talleres/index.html','Talleres','Workshops','workshops'),('estudio/index.html','El estudio','The studio','studio'),('contacto/index.html','Contacto','Contact','contact')]
    nav=''.join(f'<a href="@/{p}"'+(' aria-current="page"' if key==section else '')+'>'+t(es,en)+'</a>' for p,es,en,key in links)
    nav+=f'<a class="nav-crm" href="@/crm/index.html"'+(' aria-current="page"' if crm else '')+'>'+t('Probar CRM ↗','Try CRM ↗')+'</a><button id="lang" class="ghost" aria-label="Switch to English">EN</button>'
    breadcrumb='' if section=='home' else '<div class="wrap"><nav class="breadcrumb" aria-label="Breadcrumb">'+link('index.html','Inicio','Home','')+'<span aria-hidden="true">/</span>'+t(title,title_en)+'</nav></div>'
    html=f'''<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Demo multipágina de Isolabella Art Studio: talleres de cerámica, coworking y gestión del estudio."><title>{escape(title)} · Isolabella</title><link rel="stylesheet" href="@/assets/styles.css"><script type="module" src="@/assets/app.mjs"></script></head>
<body data-page="{section}" data-activity="{activity}" data-base="@/" data-title-es="{escape(title)}" data-title-en="{escape(title_en)}">
<a class="skip" href="#main">{t('Saltar al contenido','Skip to content')}</a>
<div class="demo-bar">{t('Propuesta de Agallart Digital · Demo · Actividades, fechas y precios de ejemplo','Proposal by Agallart Digital · Demo · Illustrative activities, dates and prices')}</div>
<header class="site-header"><a class="brand" href="@/index.html" aria-label="Isolabella · Inicio">isolabella<small>Art Studio · Valencia</small></a><button class="ghost menu-toggle" id="menu" aria-expanded="false" aria-controls="site-nav">{t('Menú','Menu')}</button><nav id="site-nav" class="site-nav" aria-label="Principal">{nav}</nav></header>
<div id="storage-warning" role="status" hidden></div>
<main id="main" class="{'crm-page' if crm else ''}">{breadcrumb}{content}</main>
<footer class="site-footer"><span>isolabella · Art Studio · Valencia<br>{t('Propuesta web + CRM por Agallart Digital','Website + CRM proposal by Agallart Digital')}</span><div class="footer-links">{link('talleres/index.html','Talleres','Workshops','')}{link('contacto/index.html','Contacto','Contact','')}{link('crm/index.html','Demo de gestión','Management demo','')}</div></footer><div id="toast" role="status" hidden></div>
</body></html>'''
    prefix=os.path.relpath(OUT, (OUT/path).parent).replace(os.sep,'/')
    html=html.replace('@/',prefix+'/')
    target=OUT/path
    target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(html,encoding='utf-8')

home='<div class="wrap"><section class="hero"><div>'+t('Barro, tiempo y buena compañía','Clay, time and good company','div','eyebrow')+'<h1>'+t('Un espacio','A space')+'<br>'+t('para','to')+' <em>'+t('crear.','create.')+'</em></h1>'+t('Clases de torno y modelado, talleres para desconectar y un espacio compartido donde dar forma a tus ideas.','Wheel throwing, hand-building workshops and a shared studio to give your ideas a shape.','p','lead')+link('talleres/index.html','Encuentra tu taller ↗','Find your workshop ↗')+'</div>'+art()+'</section><section class="section"><div class="section-title"><div>'+t('Tu próximo momento creativo','Your next creative moment','div','eyebrow')+t('Una forma de empezar.','A way to begin.','h2')+'</div>'+link('talleres/index.html','Ver todos los talleres →','Explore all workshops →','text-link')+'</div><div id="workshops" class="cards"></div></section><section class="home-links"><article>'+t('Un lugar para tus ideas.','A place for your ideas.','h2')+t('Conoce la propuesta del estudio y el espacio de coworking para seguir creando a tu ritmo.','Discover the studio and the coworking space to keep creating at your own pace.','p')+link('estudio/index.html','Descubre el estudio →','Explore the studio →','text-link')+'</article><article>'+t('¿Por dónde empezar?','Where to begin?','h2')+t('Explora los talleres o prueba una consulta de coworking. Cada actividad tiene su propia página.','Explore the workshops or try a coworking enquiry. Each activity has its own page.','p')+link('contacto/index.html','Hablemos →','Let’s talk →','text-link')+'</article></section></div>'
page(Path('index.html'),'home','Un espacio para crear','A space to create',home)

workshops='<div class="wrap">'+head('Talleres y clases','Workshops & classes','Encuentra tu forma de crear.','Find your way to create.','Un primer encuentro con el barro o un nuevo hábito para tu semana. Elige una experiencia y descubre sus detalles.','Your first encounter with clay or a new weekly ritual. Choose an experience and explore the details.')+'<div id="workshops" class="cards"></div><p class="section-note">'+t('Agenda de demostración: fechas, plazas, docentes y precios ilustrativos. No corresponde a la programación real del estudio.','Demo schedule: illustrative dates, capacity, tutors and prices. This is not the studio’s actual programme.')+'</p><section class="section"><div class="panel">'+t('¿Buscas un espacio para tu proyecto?','Looking for a space for your project?','h2')+t('La propuesta de coworking tiene su propio recorrido de consulta.','The coworking proposal has its own enquiry journey.','p')+link('estudio/index.html','Conocer el coworking →','Explore coworking →')+'</div></section></div>'
page(Path('talleres/index.html'),'workshops','Talleres y clases','Workshops & classes',workshops)

details=[
 ('wheel','torno','Tu primer encuentro con el torno.','Your first encounter with the wheel.','Una propuesta para descubrir el movimiento del barro, aprender a centrarlo y experimentar con tus primeras formas.','A proposed introduction to the movement of clay, centring and your first forms.','Sentir el barro entre las manos.','Feel the clay in your hands.','En este taller de ejemplo, el recorrido comienza con una introducción al torno y continúa con una práctica guiada. El enfoque está en explorar el proceso, sin necesidad de experiencia previa.','In this sample workshop, an introduction to the wheel leads into guided practice. The focus is on exploring the process, with no previous experience needed.',['Introducción al torno y al centrado','Exploración de formas sencillas','Tiempo de práctica guiada'],['Introduction to the wheel and centring','Exploring simple shapes','Time for guided practice']),
 ('hand','modelado','Una taza, muchas posibilidades.','One cup, so many possibilities.','Una propuesta de modelado a mano para experimentar con formas, texturas y pequeños detalles.','A proposed hand-building workshop to explore shapes, textures and small details.','Crear a tu propio ritmo.','Create at your own pace.','El taller de ejemplo plantea una primera aproximación al modelado manual. Una taza sirve como punto de partida para descubrir cómo una idea toma forma en el barro.','This sample workshop introduces hand-building. A cup is the starting point for discovering how an idea takes shape in clay.',['Introducción a técnicas manuales','Construcción de una forma sencilla','Exploración de acabados y texturas'],['Introduction to hand-building techniques','Building a simple form','Exploring finishes and textures']),
 ('weekly','clases-semanales','Haz espacio para la cerámica.','Make room for ceramics.','Una propuesta de clases semanales para explorar técnicas y dar continuidad a tus proyectos.','A proposed weekly class format to explore techniques and develop your projects.','Un hábito que toma forma.','A ritual that takes shape.','Esta ficha muestra cómo podría presentarse un grupo semanal: horario, docente, plazas y solicitudes en espera. La tarifa del ejemplo corresponde a una sesión; no es un abono real.','This page shows how a weekly group could be presented: schedule, tutor, places and a waiting list. The sample price is per session; it is not a real subscription.',['Práctica de torno y modelado','Continuidad de proyectos personales','Acompañamiento durante el proceso'],['Wheel throwing and hand-building practice','Developing personal projects','Guidance throughout the process'])
]
for key,slug,title,title_en,desc,desc_en,h2,h2en,p,pen,items,itemsen in details:
    content='<div class="wrap">'+head('Taller de ejemplo','Sample workshop',title,title_en,desc,desc_en)+'<div class="intro-grid"><article class="prose">'+tile(key)+t(h2,h2en,'h2')+t(p,pen,'p')+t('Propuesta de contenido','Suggested content','h2')+'<ul>'+''.join(t(a,b,'li') for a,b in zip(items,itemsen))+'</ul>'+t('Los materiales, la cocción, la recogida y las condiciones de reserva se concretarían con el estudio antes de publicar una oferta real.','Materials, firing, collection and booking terms would be agreed with the studio before publishing a real offering.','p','notice')+'</article><aside id="activity-details" class="booking-card"></aside></div><div class="section">'+link('talleres/index.html','← Volver a todos los talleres','← Back to all workshops','text-link')+'</div></div>'
    page(Path(f'talleres/{slug}/index.html'),'workshops',title,title_en,content,activity=key)

studio='<div class="wrap">'+head('El estudio · Valencia','The studio · Valencia','Un espacio compartido para crear.','A shared space to create.','Torno, modelado y talleres, con una propuesta de coworking para quienes quieren dar continuidad a sus proyectos.','Wheel throwing, hand-building and workshops, with a coworking proposal for people developing their own projects.')+'<section class="studio-grid">'+art()+'<article class="prose">'+t('Cada proceso tiene su tiempo.','Every process takes its own time.','h2')+t('El estudio reúne distintas formas de acercarse a la cerámica: descubrir una técnica, participar en una actividad puntual o convertir la práctica en parte de la semana.','The studio brings together different ways to explore ceramics: discovering a technique, joining a one-off activity or making practice part of your week.','p')+link('talleres/index.html','Explora las clases →','Explore the classes →')+'</article></section><section class="studio-grid"><div class="panel">'+t('Coworking de cerámica','Ceramics coworking','div','eyebrow')+t('Dale lugar a tu próximo proyecto.','Make space for your next project.','h2')+t('Una consulta permite al estudio conocer tu interés y conversar sobre disponibilidad, uso del espacio y condiciones.','An enquiry lets the studio understand your interest and discuss availability, use of the space and terms.','p')+link('reserva/index.html?actividad=cowork','Consultar coworking ↗','Enquire about coworking ↗')+'</div><article class="prose">'+t('Así sería el siguiente paso.','What would happen next.','h2')+'<ol>'+t('Dejas una solicitud desde la página de coworking.','Submit an enquiry through the coworking form.','li')+t('El equipo la recibe en su panel de gestión.','The team sees it in the management dashboard.','li')+t('Se revisan juntos las opciones y las condiciones.','Discuss options and terms together.','li')+'</ol>'+t('En esta demo, la solicitud solo se guarda en tu navegador. No se envía al estudio.','In this demo, enquiries are stored only in your browser. Nothing is sent to the studio.','p','notice')+'</article></section></div>'
page(Path('estudio/index.html'),'studio','El estudio','The studio',studio)

contact='<div class="wrap">'+head('Contacto','Contact','El primer paso es una idea.','It starts with an idea.','Tanto si quieres probar la cerámica como si buscas un espacio para crear, aquí empieza tu recorrido.','Whether you want to try ceramics or find a space to create, your journey starts here.')+'<div class="studio-grid"><article class="panel">'+t('Quiero probar un taller','I’d like to try a workshop','h2')+t('Consulta las actividades, sus horarios de ejemplo y la disponibilidad antes de solicitar una plaza.','Explore activities, sample schedules and availability before requesting a place.','p')+link('talleres/index.html','Elegir un taller →','Choose a workshop →')+'</article><article class="panel">'+t('Me interesa el coworking','I’m interested in coworking','h2')+t('Prueba cómo llegaría una consulta sobre el espacio al panel del estudio.','Try how a studio-space enquiry would appear in the dashboard.','p')+link('reserva/index.html?actividad=cowork','Hacer una consulta →','Make an enquiry →')+'</article></div><div class="prose section">'+t('Isolabella Art Studio · Valencia','Isolabella Art Studio · Valencia','h2')+t('Esta es una propuesta de experiencia web. Los datos de contacto, la dirección y los horarios oficiales se incorporarían al validar la web con el estudio.','This is a proposed website experience. Official contact details, address and opening hours would be added after reviewing the website with the studio.','p')+t('Puedes recorrer la demo y crear solicitudes ficticias. No se envían correos, mensajes ni pagos.','Explore the demo and create fictional enquiries. No emails, messages or payments are sent.','p','notice')+'</div></div>'
page(Path('contacto/index.html'),'contact','Contacto','Contact',contact)

booking='<div class="wrap">'+head('Tu próximo paso','Your next step','Solicita tu plaza.','Request your place.','Prueba el recorrido de reserva. La solicitud aparecerá en el CRM de esta demo.','Try the booking journey. Your enquiry will appear in this demo’s CRM.')+'<div class="form-layout"><div><form id="booking-form" class="form-panel">'+t('Solicitud de demostración','Demo enquiry','h2')+t('Usa datos ficticios. Esta solicitud no llega al estudio y no confirma una reserva real.','Use fictional details. This enquiry is not sent to the studio and does not confirm a real booking.','p','notice')+'<div class="form-grid"><div class="full"><label for="activity">'+t('Actividad','Activity')+'</label><select id="activity" name="activity"></select><p id="booking-availability" class="form-help" aria-live="polite"></p></div><div class="full"><label for="name">'+t('Nombre de prueba','Demo name')+'</label><input id="name" name="name" required maxlength="100" autocomplete="off" placeholder="Visitante demo"></div><div class="full"><label for="email">'+t('Correo ficticio','Fictional email')+'</label><input id="email" name="email" type="email" required maxlength="180" autocomplete="off" placeholder="visitante@example.test"></div><div><label for="people">'+t('Personas','People')+'</label><input id="people" name="people" type="number" min="1" max="8" value="1" required></div><div><label for="language">'+t('Idioma preferido','Preferred language')+'</label><select id="language" name="language"><option>Español</option><option>English</option></select></div></div><button class="submit" type="submit">'+t('Guardar solicitud de prueba →','Save demo enquiry →')+'</button><p id="form-error" role="alert" class="status-text" hidden></p></form><div id="booking-success" class="success" tabindex="-1" hidden></div></div><aside class="panel">'+t('¿Qué sucede después?','What happens next?','h2')+'<ol>'+t('La solicitud llega al panel de gestión de la demo.','The enquiry appears in the demo dashboard.','li')+t('El estudio comprueba las plazas y confirma la reserva.','The studio checks capacity and confirms the booking.','li')+t('Si no hay plazas, se añade a la lista de espera.','If there are not enough places, it joins the waiting list.','li')+'</ol>'+t('Las solicitudes pendientes no bloquean plazas. Los pagos del panel son simulados.','Pending enquiries do not hold places. Dashboard payments are simulated.','p','muted')+link('talleres/index.html','← Volver a talleres','← Back to workshops','text-link')+'</aside></div></div>'
page(Path('reserva/index.html'),'booking','Solicitar plaza','Request a place',booking)

crm='<div class="wrap"><div class="crm-head"><div>'+t('Isolabella · Panel del estudio','Isolabella · Studio dashboard','div','eyebrow')+t('Todo a mano.','Everything at hand.','h1')+t('Solicitudes, aforo, espera y pagos simulados, en un espacio de gestión separado de la web.','Enquiries, capacity, waiting lists and simulated payments, in a management space separate from the website.','p','muted')+'</div>'+link('reserva/index.html','+ Nueva solicitud','+ New enquiry')+'</div>'+t('CRM de demostración · Solo datos ficticios · Guardado local en este navegador · Sin autenticación ni cobros reales','Demo CRM · Fictional data only · Stored locally in this browser · No authentication or real payments','div','notice')+'<div id="stats" class="stats"></div><div class="tabs" role="tablist" aria-label="CRM"><button class="ghost" id="tab-requests" role="tab" aria-controls="panel-requests" aria-selected="true" data-tab="requests">'+t('Solicitudes y pagos','Enquiries & payments')+'</button><button class="ghost" id="tab-capacity" role="tab" aria-controls="panel-capacity" aria-selected="false" tabindex="-1" data-tab="capacity">'+t('Agenda y aforo','Schedule & capacity')+'</button></div><section id="panel-requests" role="tabpanel" aria-labelledby="tab-requests"><div class="tools"><div class="search-wrap"><label for="search">'+t('Buscar solicitud','Search enquiries')+'</label><input id="search" type="search" placeholder="Nombre, correo, actividad…" autocomplete="off"></div><div class="status-wrap"><label for="status">'+t('Estado','Status')+'</label><select id="status"><option value="all" data-es="Todos" data-en="All">Todos</option><option value="pending" data-es="Pendiente" data-en="Pending">Pendiente</option><option value="confirmed" data-es="Confirmada" data-en="Confirmed">Confirmada</option><option value="wait" data-es="En espera" data-en="Waiting">En espera</option><option value="cancelled" data-es="Cancelada" data-en="Cancelled">Cancelada</option></select></div></div><div id="requests" class="table-wrap" tabindex="0" aria-label="Solicitudes"></div></section><section id="panel-capacity" role="tabpanel" aria-labelledby="tab-capacity" hidden><div id="capacity" class="capacity"></div></section><div class="crm-bottom">'+t('Los cambios se comparten entre las páginas de esta demo en el mismo navegador. No se envían al estudio. Al cancelar, las plazas vuelven a estar disponibles.','Changes are shared across this demo’s pages in the same browser. Nothing is sent to the studio. Cancelling releases the places.','p','muted')+'<button id="reset" class="ghost">'+t('Restablecer demo','Reset demo')+'</button></div><dialog id="reset-dialog">'+t('¿Restablecer los datos?','Reset the data?','h2')+t('Se borrarán las solicitudes de prueba de este navegador y se recuperarán los ejemplos iniciales.','Demo enquiries in this browser will be removed and the initial examples will be restored.','p')+'<div class="actions"><button id="reset-cancel" class="ghost">'+t('Conservar cambios','Keep changes')+'</button><button id="reset-confirm">'+t('Restablecer','Reset')+'</button></div></dialog></div>'
page(Path('crm/index.html'),'crm','Panel del estudio','Studio dashboard',crm,crm=True)
print(f'Generated 9 independent pages in {OUT.name}/.')
